def decay_compression(value, decay_rate=0.1):
    return value / (1 + decay_rate * abs(value))

# Modified polynomial model with decay
def zeta_poly_decay(p, a, b, c, decay_rate=0.1):
    raw_value = a + b * H(p) + c * (H(p) ** 2)
    return decay_compression(raw_value, decay_rate)

# Modified exponential model with decay
def zeta_exp_decay(p, a, b, decay_rate=0.1):
    raw_value = a * np.exp(b * H(p))
    compressed_value = iterative_exp_compression(raw_value)  # Use iterative compression first
    return decay_compression(compressed_value, decay_rate)

