class ZetaApproximation:
    """Base class for zeta function approximation."""
    def __init__(self, a, b):
        self.a = a
        self.b = b

    def predict(self, H_p):
        """Logarithmic approximation (base model)."""
        return self.a + self.b * np.log(H_p + 1e-10)  # Avoid log(0)


class PolynomialApproximation(ZetaApproximation):
    """Polynomial approximation with decay."""
    def __init__(self, a, b, c, decay_rate=0.1):
        super().__init__(a, b)
        self.c = c
        self.decay_rate = decay_rate

    def predict(self, H_p):
        """Polynomial approximation with decay."""
        raw_value = self.a + self.b * H_p + self.c * (H_p ** 2)
        return decay_compression(raw_value, self.decay_rate)


class ExponentialApproximation(ZetaApproximation):
    """Exponential approximation with decay."""
    def __init__(self, a, b, decay_rate=0.1):
        super().__init__(a, b)
        self.decay_rate = decay_rate

    def predict(self, H_p):
        """Exponential approximation with iterative and decay-based compression."""
        raw_value = self.a * np.exp(self.b * H_p)
        compressed_value = iterative_exp_compression(raw_value)
        return decay_compression(compressed_value, self.decay_rate)


# Instantiate models with best-fit parameters
log_model = ZetaApproximation(*best_log_params)
poly_model = PolynomialApproximation(*best_poly_decay_params, decay_rate=0.1)
exp_model = ExponentialApproximation(*best_exp_decay_params, decay_rate=0.1)

# Evaluate all models
